import { NextResponse, type NextRequest } from 'next/server'

interface Post {
  id: number
  title: string
  content: string
  createdAt: string
}

interface UpdatedPost {
  id: number
  title: string
  content: string
  updatedAt: string
}

interface DeleteResult {
  message: string
}

interface RouteParams {
  params: Promise<{ id: string }>
}

export async function GET(
  _request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse<Post>> {
  const { id } = await params

  const post: Post = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(
  request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse<UpdatedPost>> {
  const { id } = await params
  const body = (await request.json()) as Partial<UpdatedPost>
  const { title, content } = body

  const updatedPost: UpdatedPost = {
    id: parseInt(id, 10),
    title: title ?? `Post ${id}`,
    content: content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost, { status: 200 })
}

export async function DELETE(
  _request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse<DeleteResult>> {
  const { id } = await params

  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}

